const opportunity = $('Get Opportunity').first().json;

const amount = Number(opportunity.Amount || 0);
const stage = opportunity.StageName || '';

const expectedRoles = [
  'Executive Sponsor',
  'Economic Buyer'
];

if (amount >= 50000) {
  expectedRoles.push('Technical Buyer');
}

if (amount >= 250000) {
  expectedRoles.push('Finance');
  expectedRoles.push('Procurement');
}

if (
  stage === 'Negotiation' ||
  stage === 'Proposal/Price Quote'
) {
  expectedRoles.push('Legal');
}

return [
  {
    json: {
      opportunityId: opportunity.Id,
      opportunityName: opportunity.Name,
      accountId: opportunity.AccountId,
      amount,
      stage,
      expectedStakeholderRoles: [...new Set(expectedRoles)],
      expectedStakeholderCount: [...new Set(expectedRoles)].length
    }
  }
];

const contacts = $('Get Opportunity Contacts').all()

const emails = contacts
  .map(item => item.json.Contact?.Email || item.json.Contact?.email)
  .filter(Boolean)
  .map(email => email.trim().toLowerCase());

const domains = emails
  .map(email => email.split('@')[1])
  .filter(Boolean);

return [
  {
    json: {
      opportunityId: $('Determine Expected Stakeholder Roles').first().json.opportunityId,
      customerEmails: [...new Set(emails)],
      customerDomains: [...new Set(domains)]
    }
  }
];

