const items = $input.all();

const interactions = [];

for (const item of items) {
  const data = item.json;

  // Adjust these fields according to your actual Gmail output.
  if (data.subject || data.threadId || data.from) {
    interactions.push({
      type: 'email',
      date: data.date || data.internalDate,
      subject: data.subject || '',
      from: data.from || '',
      to: data.to || '',
      cc: data.cc || '',
      body: data.textPlain || data.snippet || ''
    });
  } else {
    const attendees = data.attendees || [];

    interactions.push({
      type: 'meeting',
      date: data.start?.dateTime || data.start || '',
      subject: data.summary || data.name || '',
      attendees: attendees.map(a => a.email || a).filter(Boolean),
      body: data.description || ''
    });
  }
}

return [
  {
    json: {
      opportunityId: $('Prepare Customer Search Data').first().json.opportunityId,
      interactions
    }
  }
];

const data = $input.first().json;

const errors = [];

// Required fields
if (!data.opportunityId) {
  errors.push('Missing opportunityId');
}

if (!data.opportunityName) {
  errors.push('Missing opportunityName');
}

// Validate risk level
const validRiskLevels = ['LOW', 'MEDIUM', 'HIGH'];

if (!validRiskLevels.includes(data.riskLevel)) {
  errors.push('Invalid riskLevel');
}

// Validate risk score
if (
  typeof data.riskScore !== 'number' ||
  data.riskScore < 0 ||
  data.riskScore > 100
) {
  errors.push('riskScore must be a number between 0 and 100');
}

// Validate arrays
const arrayFields = [
  'expectedStakeholderRoles',
  'engagedStakeholderRoles',
  'missingStakeholderRoles',
  'unknownStakeholderRoles',
  'evidence'
];

for (const field of arrayFields) {
  if (!Array.isArray(data[field])) {
    errors.push(`${field} must be an array`);
  }
}

// Validate recommendation
if (!data.recommendation) {
  errors.push('Missing recommendation');
}

// Return validation result
return [
  {
    json: {
      ...data,
      validation: {
        valid: errors.length === 0,
        errors
      }
    }
  }
];

const input = $input.first().json;

// Get AI response text
const text = input.output?.[0]?.content?.[0]?.text;

if (!text) {
  throw new Error('AI analysis response text not found');
}

// Parse JSON returned by OpenAI
let analysis;

try {
  analysis = JSON.parse(text);
} catch (error) {
  throw new Error(`Invalid JSON returned by OpenAI: ${error.message}`);
}

// Return parsed JSON as normal n8n JSON
return [
  {
    json: analysis
  }
];

