const expected = $('Determine Expected Stakeholder Roles').first().json;
const contacts = $('Get Opportunity Contacts').all();
const interactionData = $('Normalize Stakeholder Interactions').first().json;

const contactList = contacts.map(item => {
  const c = item.json;

  return {
    name: c.Name || c.name,
    email: c.Email || c.email,
    title: c.Title || c.title,
    department: c.Department || c.department
  };
});

return [
  {
    json: {
      opportunityId: expected.opportunityId,
      opportunityName: expected.opportunityName,
      amount: expected.amount,
      stage: expected.stage,
      expectedStakeholderRoles: expected.expectedStakeholderRoles,
      contacts: contactList,
      interactions: interactionData.interactions
    }
  }
];

const data = $('Prepare Customer Search Data').first().json;

const query = data.customerEmails.length > 0
  ? data.customerEmails
      .map(email => `(from:${email} OR to:${email})`)
      .join(' OR ')
  : 'label:SENT';

return [{
  json: {
    customerEmails: data.customerEmails,
    customerDomains: data.customerDomains,
    gmailQuery: query
  }
}];
